namespace Paramore.Brighter.Kafka.Tests.MessagingGateway.PartitionKey.Reactor;

/// <summary>
/// A nacked message is redelivered, and a message queued behind it is not blocked meanwhile.
/// Messages are identified by id, never by arrival order; a redelivery is the nacked id seen a
/// second time (ADR 0066, Conventions the canonical templates follow).
/// </summary>
[Property("Category", "Kafka")]
[NotInParallel("Kafka")]
public class WhenNackingAMessageItShouldBeRedelivered : IDisposable
{
    private readonly IAmAMessageGatewayReactorProvider _messageGatewayProvider;
    private readonly IAmAMessageBuilder _messageBuilder;
    private readonly IAmAMessageAssertion _messageAssertion;

    private List<Message> _sentMessages = [];

    private Paramore.Brighter.MessagingGateway.Kafka.KafkaSubscription? _subscription;
    private Paramore.Brighter.MessagingGateway.Kafka.KafkaPublication? _publication;

    private IAmAMessageProducerSync? _producer = null;
    private IAmAChannelSync? _channel = null;

    public WhenNackingAMessageItShouldBeRedelivered()
    {
        _messageGatewayProvider = new Paramore.Brighter.Kafka.Tests.MessagingGateway.KafkaPartitionKeyMessageGatewayProvider();
        _messageBuilder = new FifoMessageBuilder();
        _messageAssertion = new KafkaMessageAssertion();
    }

    public void Dispose()
    {
        _messageGatewayProvider.CleanUp(_producer, _channel, _sentMessages);
    }

    [Test]
    
    public async Task When_nacking_a_message_it_should_be_redelivered()
    {
        // Arrange
        _publication = _messageGatewayProvider.CreatePublication(_messageGatewayProvider.GetOrCreateRoutingKey());
        _subscription = _messageGatewayProvider.CreateSubscription(_publication.Topic!,
            _messageGatewayProvider.GetOrCreateChannelName(),
            OnMissingChannel.Create);

        _producer = _messageGatewayProvider.CreateProducer(_publication);
        _channel = _messageGatewayProvider.CreateChannel(_subscription);

        var message = _messageBuilder.SetTopic(_publication.Topic!)
            .SetMessageId(Id.Random())
            .SetBody(Encoding.UTF8.GetBytes(Id.Random().ToString()))
            .Build();
        _sentMessages.Add(message);

        _producer.Send(message);

        // Act
        var received = _channel.Receive(TimeSpan.FromMilliseconds(15000));
        await Assert.That(received.Header.MessageType).IsNotEqualTo(MessageType.MT_NONE);

        _channel.Nack(received);

        // Assert
        var redelivered = new Message();
        var stopwatch = Stopwatch.StartNew();
        while (stopwatch.Elapsed < TimeSpan.FromSeconds(30))
        {
            redelivered = _channel.Receive(TimeSpan.FromMilliseconds(500));
            if (redelivered.Header.MessageType != MessageType.MT_NONE)
            {
                break;
            }
        }

        await Assert.That(redelivered.Header.MessageType).IsNotEqualTo(MessageType.MT_NONE);
        await AssertIsRedeliveryOf(message, redelivered);
    }

    [Test]
    
    public async Task When_nacking_first_of_two_messages_should_redeliver_nacked_then_receive_second()
    {
        // Arrange
        _publication = _messageGatewayProvider.CreatePublication(_messageGatewayProvider.GetOrCreateRoutingKey());
        _subscription = _messageGatewayProvider.CreateSubscription(_publication.Topic!,
            _messageGatewayProvider.GetOrCreateChannelName(),
            OnMissingChannel.Create);

        _producer = _messageGatewayProvider.CreateProducer(_publication);
        _channel = _messageGatewayProvider.CreateChannel(_subscription);

        var firstSent = _messageBuilder.SetTopic(_publication.Topic!)
            .SetMessageId(Id.Random())
            .SetBody(Encoding.UTF8.GetBytes(Id.Random().ToString()))
            .Build();
        _sentMessages.Add(firstSent);

        var secondSent = _messageBuilder.SetTopic(_publication.Topic!)
            .SetMessageId(Id.Random())
            .SetBody(Encoding.UTF8.GetBytes(Id.Random().ToString()))
            .Build();
        _sentMessages.Add(secondSent);

        _producer.Send(firstSent);
        _producer.Send(secondSent);

        // Act
        var receivedForNack = _channel.Receive(TimeSpan.FromMilliseconds(15000));
        await Assert.That(receivedForNack.Header.MessageType).IsNotEqualTo(MessageType.MT_NONE);

        var nackedMessage = _sentMessages.Single(m => m.Header.MessageId == receivedForNack.Header.MessageId);
        var theOtherMessage = _sentMessages.Single(m => m.Header.MessageId != nackedMessage.Header.MessageId);

        _channel.Nack(receivedForNack);

        // Assert
        var observedIds = new HashSet<string>();
        var stopwatch = Stopwatch.StartNew();
        while (stopwatch.Elapsed < TimeSpan.FromSeconds(30) && observedIds.Count < 2)
        {
            var received = _channel.Receive(TimeSpan.FromMilliseconds(500));
            if (received.Header.MessageType == MessageType.MT_NONE)
            {
                continue;
            }

            observedIds.Add(received.Header.MessageId.Value);
            _channel.Acknowledge(received);
        }

        await Assert.That(observedIds).Contains(nackedMessage.Header.MessageId.Value);
        await Assert.That(observedIds).Contains(theOtherMessage.Header.MessageId.Value);
    }

    // HandledCount may rise on redelivery (ADR 0077, Conformance oracle change for the redelivery
    // arms), so it is normalised to let the shared assertion compare the rest of the header.
    private async Task AssertIsRedeliveryOf(Message message, Message redelivered)
    {
        await Assert.That(redelivered.Header.HandledCount >= message.Header.HandledCount).IsTrue().Because($"Redelivered HandledCount {redelivered.Header.HandledCount} must be >= sent {message.Header.HandledCount} (R-1)");
        redelivered.Header.HandledCount = message.Header.HandledCount;
        await _messageAssertion.AssertAsync(message, redelivered);
    }}